void validate_user_password(struct pdf_struct *pdf, int R, const char *O, const char *U, int32_t P, int EM, unsigned length, unsigned oulen) {
    unsigned char key[32]; // Max size for MD5 and SHA-256
    unsigned char hash[32];
    size_t hash_len = 0;

    if (R == 2) {
        // Use MD5 for revision 2
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, U, oulen);
        MD5_Final(key, &md5);
        hash_len = 16;
    } else if (R == 3) {
        // Use SHA-256 for revision 3
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, U, oulen);
        SHA256_Final(key, &sha256);
        hash_len = 32;
    } else {
        // Unsupported revision number
        pdf->error = 1;
        return;
    }

    if (U[0] == '\0') {
        // Empty user password
        pdf->empty_password = 1;
        return;
    }

    // Truncate or pad the key to the desired length
    if (hash_len < length) {
        // Padding not supported in this context
        pdf->error = 1;
        return;
    }

    // Copy the computed key into the PDF structure
    for (unsigned i = 0; i < length; ++i) {
        pdf->encryption_key[i] = key[i];
    }

    // Set other flags based on permissions and encryption method
    pdf->permissions = P;
    pdf->encryption_method = EM;
    pdf->valid_password = 1;
}

