        // Use MD5 hashing for revision 2
        MD5_CTX md5;
        MD5_Init(&md5);
        MD5_Update(&md5, U, strlen(U));
        MD5_Update(&md5, O, strlen(O));
        MD5_Final(key, &md5);
        pdf->permissions = P;
    } else if (R == 3) {
        if (strlen(U) == 0) {
            // For revision 3, empty password is valid
            pdf->permissions = P;
            return;
