        SHA256_Init(&sha256);
        SHA256_Update(&sha256, U, strlen(U));
        SHA256_Update(&sha256, O, strlen(O));
        SHA256_Final(key, &sha256);
        pdf->permissions = P;
    } else {
        // Unsupported revision number
        pdf->permissions = 0;
        return;
    }

