void validate_user_password(struct pdf_struct *pdf, int R, const char *O, const char *U, int32_t P, int EM, unsigned length, unsigned oulen) {
    if (R == 2) {
        if (U == nullptr || strlen(U) == 0) {
            pdf->empty_user_password = true;
            pdf->encryption_key = compute_md5_key(U, O, P, length);
        } else {
            pdf->empty_user_password = false;
            pdf->encryption_key = compute_md5_key(U, U, P, length);
        }
    } else if (R == 3) {
        if (U == nullptr || strlen(U) == 0) {
            pdf->empty_user_password = true;
