            } else {
                pdf->encryption_key = compute_sha256_key(U, O, P | 0x80000000, length);
            }
        } else {
            pdf->empty_user_password = false;
            pdf->encryption_key = compute_sha256_key(U, U, P, length);
        }
    } else {
        throw std::invalid_argument("Unsupported revision number");
    }

